-- TrueValue relational schema (SQLite). Prototype UI uses JSON; SQL is for a future backend.
PRAGMA foreign_keys = ON;
CREATE TABLE DataSource (source_id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,trust_tier INTEGER CHECK(trust_tier BETWEEN 1 AND 4 OR trust_tier IS NULL),url TEXT,last_refreshed TEXT);
CREATE TABLE Company (company_id TEXT PRIMARY KEY,legal_name TEXT NOT NULL,brand_names_json TEXT NOT NULL DEFAULT '[]',parent_company_id TEXT REFERENCES Company(company_id),country_of_incorporation TEXT,headquarters_city TEXT,headquarters_province TEXT,ownership_type TEXT CHECK(ownership_type IN ('Canadian','foreign','mixed','unknown')),percent_canadian_owned REAL CHECK(percent_canadian_owned BETWEEN 0 AND 100 OR percent_canadian_owned IS NULL),business_number TEXT,registry_source_id TEXT REFERENCES DataSource(source_id),is_local INTEGER NOT NULL DEFAULT 0,latitude REAL,longitude REAL,ownership_status TEXT NOT NULL CHECK(ownership_status IN ('Verified','Claimed','Unknown')));
CREATE TABLE Product (product_id TEXT PRIMARY KEY,barcode TEXT UNIQUE,name TEXT NOT NULL,brand TEXT,company_id TEXT REFERENCES Company(company_id),category TEXT,country_of_manufacture TEXT,country_of_origin_components_json TEXT NOT NULL DEFAULT '[]',packaging_materials_json TEXT NOT NULL DEFAULT '[]',recyclable_in_regina INTEGER,recyclable_in_province INTEGER,compostable INTEGER,reusable INTEGER,plastic_weight_estimate_g REAL,packaging_status TEXT CHECK(packaging_status IN ('Verified','Claimed','Unknown')),packaging_source_id TEXT REFERENCES DataSource(source_id),source_id TEXT NOT NULL REFERENCES DataSource(source_id));
CREATE TABLE Certification (certification_id TEXT PRIMARY KEY,name TEXT NOT NULL,issuing_body TEXT,dimension_id TEXT,verification_url TEXT,validity_start TEXT,validity_end TEXT,source_id TEXT REFERENCES DataSource(source_id));
CREATE TABLE ProductCertification (product_id TEXT REFERENCES Product(product_id),certification_id TEXT REFERENCES Certification(certification_id),status TEXT NOT NULL CHECK(status IN ('Verified','Claimed','Expired','Unknown')),source_id TEXT REFERENCES DataSource(source_id),PRIMARY KEY(product_id,certification_id));
CREATE TABLE Claim (claim_id TEXT PRIMARY KEY,product_id TEXT REFERENCES Product(product_id),company_id TEXT REFERENCES Company(company_id),dimension_id TEXT NOT NULL,claim_text TEXT NOT NULL,claim_source TEXT,evidence_url TEXT,status TEXT NOT NULL CHECK(status IN ('Verified','Claimed','Disputed','Unknown')),verified_by TEXT REFERENCES Certification(certification_id),source_id TEXT NOT NULL REFERENCES DataSource(source_id),raw_score REAL CHECK(raw_score BETWEEN 0 AND 100 OR raw_score IS NULL),confidence REAL CHECK(confidence BETWEEN 0 AND 1 OR confidence IS NULL),coverage_percent REAL CHECK(coverage_percent BETWEEN 0 AND 100 OR coverage_percent IS NULL),CHECK(product_id IS NOT NULL OR company_id IS NOT NULL));
CREATE TABLE UserProfile (user_id TEXT PRIMARY KEY,home_location_json TEXT,budget_sensitivity TEXT CHECK(budget_sensitivity IN ('low','medium','high')),budget_cad REAL CHECK(budget_cad>=0));
CREATE TABLE PriorityWeight (user_id TEXT REFERENCES UserProfile(user_id),dimension_id TEXT NOT NULL,weight REAL NOT NULL CHECK(weight BETWEEN 0 AND 100),PRIMARY KEY(user_id,dimension_id));
-- Score is calculated on request and NOT persisted as an authoritative fact.
-- Result fields: score_id, product_id, user_id, dimension_id, raw_score, confidence,
-- coverage_percent, breakdown_json, computed_at, model_version.
CREATE TABLE Retailer (retailer_id TEXT PRIMARY KEY,name TEXT NOT NULL,latitude REAL,longitude REAL,address TEXT,company_id TEXT REFERENCES Company(company_id),is_local INTEGER,osm_id TEXT,categories_json TEXT,hours_json TEXT,source_id TEXT REFERENCES DataSource(source_id));
CREATE TABLE PriceObservation (price_id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES Product(product_id),retailer_id TEXT NOT NULL REFERENCES Retailer(retailer_id),price REAL NOT NULL CHECK(price>=0),currency TEXT NOT NULL,observed_at TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES DataSource(source_id));
